/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.5.1/userguide/building_java_projects.html in the Gradle documentation.
 * This project uses @Incubating APIs which are subject to change.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    id 'application'
    id 'org.springframework.boot' version '3.2.0'
    id 'io.spring.dependency-management' version '1.1.4'
}

// ── Project coordinates ───────────────────────────────────────
// group + version + name (from settings.gradle) form the
// Maven coordinates: com.minios:mini-os-sim:1.0.0-SNAPSHOT
group = 'org.os.simulator'
version = '1.0.0-SNAPSHOT'

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // This dependency is used by the application.
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-websocket'
    implementation 'com.fasterxml.jackson.datatype:jackson-datatype-jsr310'
    compileOnly 'org.projectlombok:lombok'
    annotationProcessor 'org.projectlombok:lombok'
    // 'testImplementation' = only on the test classpath, not in production JAR.
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
    // Lombok in tests too (for @Slf4j in test classes if needed)
    testCompileOnly 'org.projectlombok:lombok'
    testAnnotationProcessor 'org.projectlombok:lombok'
}

// ── Test configuration ────────────────────────────────────────
tasks.named('test') {
    // JUnit 5 requires this. Without it Gradle uses the old JUnit 4 runner
    // and none of your @Test methods will execute.
    useJUnitPlatform()

    // Print each test name as it runs — useful for a project like this
    // where tests map directly to OS concepts you've just learned.
    testLogging {
        events "passed", "skipped", "failed"
        showStandardStreams = false   // set true if you want System.out in test output
    }
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = 'org.os.simulator.App'
}

/*
